class LmdbHashJoinInputFrameTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String SHADOW_QUERY = """
			SELECT ?x WHERE {
			  { {} UNION {} }
			  { SELECT (CONCAT("local:", STR(UUID())) AS ?x) WHERE {} }
			}
			""";

	@Test
	void lazyNativeRequestInputYieldsToIndependentLocalOutputAndSurvivesClose(@TempDir File directory)
			throws Exception {
		CapturingStore store = new CapturingStore(directory);
		SailRepository repository = new SailRepository(store);
		repository.init();
		List<BindingSet> retained = new ArrayList<>();
		DirectResult direct;
		LmdbLiteral ambient;
		try {
			try (var connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:hash:subject"), VF.createIRI("urn:hash:predicate"),
						VF.createLiteral("ambient"));
				long id = store.values.getId(VF.createLiteral("ambient"), false);
				assertThat(id).isNotNegative();
				// A real mapped native ID with its store revision creates an ordinary uninitialized native shell.
				ambient = new LmdbLiteral(store.values.getRevision(), id);
				assertThat(ambient.isInitialized()).isFalse();
				SailTupleQuery query = connection.prepareTupleQuery(QueryLanguage.SPARQL, SHADOW_QUERY, null);
				query.setBinding("x", ambient);
				try (TupleQueryResult result = query.evaluate()) {
					result.forEachRemaining(retained::add);
				}
				assertThat(retained).hasSize(2);
				String local = retained.getFirst().getValue("x").stringValue();
				assertThat(local).startsWith("local:");
				assertThat(retained).allSatisfy(row -> assertThat(row.getValue("x").stringValue()).isEqualTo(local));
				direct = evaluateForcedHash(store, new LmdbLiteral(store.values.getRevision(), id), false);
				assertThat(direct.rows()).hasSize(2);
				assertThat(direct.rows()).allSatisfy(row -> assertThat(row.getValue("x").stringValue())
						.isEqualTo("local:1"));
			}
		} finally {
			repository.shutDown();
		}
		assertThat(ambient.getLabel()).isEqualTo("ambient");
		assertThat(direct.capturedNative().stringValue()).isEqualTo("ambient");
		assertThat(direct.rows()).allSatisfy(row -> assertThat(row.getValue("x").stringValue()).isEqualTo("local:1"));
		assertThat(retained).allSatisfy(row -> assertThat(row.getValue("x").stringValue()).startsWith("local:"));
	}

	@Test
	void nativeLocallyProducedValuesStillRejectConflictingSubselectOutputs(@TempDir File directory) throws Exception {
		CapturingStore store = new CapturingStore(directory);
		SailRepository repository = new SailRepository(store);
		repository.init();
		DirectResult direct;
		try {
			try (var connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:hash:subject"), VF.createIRI("urn:hash:predicate"),
						VF.createLiteral("local-left"));
				String query = "SELECT ?x WHERE { <urn:hash:subject> <urn:hash:predicate> ?x . "
						+ "{ SELECT ?x WHERE { BIND(\"local-right\" AS ?x) } } }";
				try (TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
					assertThat(result.hasNext()).isFalse();
				}
				long id = store.values.getId(VF.createLiteral("local-left"), false);
				assertThat(id).isNotNegative();
				direct = evaluateForcedHash(store, new LmdbLiteral(store.values.getRevision(), id), true);
				assertThat(direct.rows()).isEmpty();
			}
		} finally {
			repository.shutDown();
		}
		assertThat(direct.capturedNative().stringValue()).isEqualTo("local-left");
	}

	/** A real paired dictionary owner plus an algebra hint makes the physical hit independent of planner choices. */
	private static DirectResult evaluateForcedHash(CapturingStore store, LmdbLiteral nativeInput, boolean localInput) {
		assertThat(nativeInput.isInitialized()).isFalse();
		AtomicInteger calls = new AtomicInteger();
		AtomicInteger nativeCaptures = new AtomicInteger();
		AtomicReference<Value> capturedNative = new AtomicReference<>();
		Function function = new Function() {
			@Override
			public String getURI() {
				return "urn:test:lmdb-hash-input-frame:volatile";
			}

			@Override
			public boolean mustReturnDifferentResult() {
				return true;
			}

			@Override
			public Value evaluate(ValueFactory factory, Value... args) {
				return factory.createLiteral("local:" + calls.incrementAndGet());
			}
		};
		FunctionRegistry.getInstance().add(function);
		try (LmdbSailStore.DatasetAdmission admission = store.getBackingStore()
				.beginDatasetAdmission(IsolationLevels.SNAPSHOT_READ, null)) {
			admission.view().requireDictionaryTermSnapshot();
			OwnedValueCapturer delegate = (OwnedValueCapturer) store.values
					.valueCapturer(admission.view().valueSnapshot());
			OwnedValueCapturer capturer = new OwnedValueCapturer() {
				@Override
				public Value apply(Value value) {
					Value captured = delegate.apply(value);
					if (value == nativeInput) {
						nativeCaptures.incrementAndGet();
						capturedNative.set(captured);
					}
					return captured;
				}

				@Override
				public boolean owns(Value value) {
					return delegate.owns(value);
				}
			};
			TripleSource source = new TripleSource() {
				@Override
				public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
						Value object, Resource... contexts) {
					return new EmptyIteration<>();
				}

				@Override
				public ValueFactory getValueFactory() {
					return VF;
				}

				@Override
				public OwnedValueCapturer getValueCapturer() {
					return capturer;
				}
			};
			QueryBindingSet incoming = new QueryBindingSet();
			TupleExpr left;
			if (localInput) {
				QueryBindingSet local = new QueryBindingSet();
				local.addBinding("x", nativeInput);
				BindingSetAssignment assignment = new BindingSetAssignment();
				assignment.setBindingSets(List.of(local));
				left = assignment;
			} else {
				incoming.addBinding("x", nativeInput);
				left = new Union(new SingletonSet(), new SingletonSet());
			}
			Projection right = new Projection(new Extension(new SingletonSet(),
					new ExtensionElem(new FunctionCall(function.getURI()), "x")),
					new ProjectionElemList(new ProjectionElem("x")));
			Join join = new Join(left, right);
			join.setStringMetricPlanned("optimizer.joinAlgorithmHint", "hash");
			join.setRuntimeTelemetryEnabled(true);
			QueryRoot root = new QueryRoot(new Projection(join, new ProjectionElemList(new ProjectionElem("x"))));
			List<BindingSet> rows = new ArrayList<>();
			try (CloseableIteration<BindingSet> result = new DefaultEvaluationStrategy(source, null).precompile(root)
					.evaluate(localInput ? EmptyBindingSet.getInstance() : incoming)) {
				result.forEachRemaining(rows::add);
			}
			assertThat(join.getAlgorithmName()).isEqualTo(HashJoinIteration.class.getSimpleName());
			assertThat(join.getLongMetricActual("actualCostHashBuildRows")).isPositive();
			assertThat(calls).hasValue(1);
			assertThat(nativeCaptures).hasValue(1);
			assertThat(capturedNative.get()).isNotNull();
			assertThat(capturer.owns(capturedNative.get())).isTrue();
			return new DirectResult(List.copyOf(rows), capturedNative.get());
		} finally {
			FunctionRegistry.getInstance().remove(function);
		}
	}

	private record DirectResult(List<BindingSet> rows, Value capturedNative) {
	}

	private static final class CapturingStore extends LmdbStore {
		private ValueStore values;

		private CapturingStore(File directory) {
			super(directory, new LmdbStoreConfig().setSketchEstimatorEnabled(false)
					.setInlineLiterals(false)
					.setFrontierEstimatorMode(FrontierEstimatorMode.OFF));
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean estimatorEnabled) throws IOException, SailException {
			return new LmdbSailStore(directory, properties, config, estimatorEnabled,
					(valueDirectory, valueProperties, valueConfig) -> values = new ValueStore(valueDirectory,
							valueProperties, valueConfig),
					TripleStore::new);
		}
	}
}
